INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Chelsea Piers Athletic Club Stamford Summer Camps', 'Chelsea Piers', 'https://www.chelseapiers.com/athleticclub-stamford/summer-camps', NULL, NULL, NULL, '1 Blachley Rd', 'Stamford', 'CT', '06902', 'Connecticut', 'day', ARRAY['sports']::text[], NULL, ARRAY['soccer','basketball','volleyball','tennis','baseball','wiffleball','floor hockey','dodgeball','pickleball','gymnastics','ninja/parkour','ice hockey','hockey goaltending','ice skating','rock climbing','swimming','arts and crafts','dance']::text[], NULL, 3, 18, NULL, NULL, 'Weekly sports day camps at Chelsea Piers'' Athletic Club in Stamford: a general multi-sport camp (Camp Chelsea) and single-sport camps such as hockey, gymnastics, tennis, squash, soccer and ninja/parkour. Full-day camps for ages 5-13 run 8:45am-3:45pm with lunch included; preschool camps for ages 3-5 run 9am-12pm or 9am-2pm. You can enroll one week at a time.', NULL, NULL, 449.65, 849.4, 810.4, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, 'Indoor pool. Preschool Gymnastics + Swimming and Preschool Tennis + Swimming camps (ages 3-5) spend the afternoon in a "warm water pool" working on basic swim technique and pool safety.', NULL, NULL, 2026, '5dea9c3b-881b-5288-9f24-fdb886d32fcd', 'chelsea-piers-athletic-club-stamford-summer-camps-stamford', ST_GeogFromText('SRID=4326;POINT(-73.5387 41.0534)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.chelseapiers.com/athleticclub-stamford','https://www.chelseapiers.com/athleticclub-stamford/summer-camps','https://www.chelseapiers.com/athleticclub-stamford/summer-camps?page=2','https://www.chelseapiers.com/athleticclub-stamford/summer-camps?page=3']::text[], '2026-11-13', '2026-11-13', TRUE),
('Darien Nature Center Summer Camp', 'Darien Nature Center', 'https://www.dariennaturecenter.org/summer-camp-2026', NULL, 'registration@dariennaturecenter.org', '203-655-7459', '120 Brookside Road', 'Darien', 'CT', '06820', 'Connecticut', 'day', ARRAY['nature','STEM']::text[], NULL, ARRAY['animal care and animal ambassadors','gardening','orienteering','outdoor survival skills','fire building and outdoor cooking','nature art','geology and fossils','pond and creek exploration','hiking','nature journaling','evening campfire and night hike (Eco Explorers Week 2)']::text[], NULL, 3, 10, NULL, NULL, 'Nature day camp at Darien Nature Center and Cherry Lawn Park, Monday to Friday from 9:30 AM to 2:00 PM, with a different theme each week. Campers ages 3–6 are in "Our Living Planet" and ages 7–10 are in "Eco Explorers."', NULL, NULL, 528, 710, 710, 'week', NULL, NULL, NULL, TRUE, 'If you cancel by May 1, 2026, you get a 50% refund. There are no refunds after May 1, and no credits for withdrawals. Card processing fees are never refunded. Payments are not refunded if camp temporarily closes for reasons beyond the center''s control.', NULL, NULL, NULL, NULL, 2026, '0459774b-afd3-5500-8bdf-f81837e262c6', 'darien-nature-center-summer-camp-darien', ST_GeogFromText('SRID=4326;POINT(-73.469 41.0776)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.dariennaturecenter.org/summer-camp-2026']::text[], '2026-11-13', '2026-11-13', TRUE),
('Darien Parks & Recreation Youth Summer Camps', 'Darien Parks & Recreation', 'https://www.darienct.gov/1649/Youth-Summer-Camps', 'https://anc.apm.activecommunities.com/darienparksandrec/home?onlineSiteId=0&from_original_cui=true', NULL, '203-656-7300', NULL, 'Darien', 'CT', '06820', 'Connecticut', 'day', NULL, NULL, NULL, NULL, NULL, NULL, 1, 9, 'The Town of Darien runs four youth day camps grouped by the grade a child enters in the fall: Stony Brook Camp (Grade 1), Settlers Camp (Grades 2-3) and Mather Camp (Grades 4-6) at Tokeneke Elementary School, and Middle School Camp (Grades 7-9) at The Depot. Camp runs 8:30am-3:00pm, June 21 to July 30, 2027, booked by the week; Middle School Camp meets Monday to Thursday.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '50d9dfa5-a4cd-5aa3-a688-e9203c11b123', 'darien-parks-and-recreation-youth-summer-camps-darien', ST_GeogFromText('SRID=4326;POINT(-73.469 41.0776)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.darienct.gov/1649/Youth-Summer-Camps','https://www.darienct.gov/DocumentCenter/View/8639/Registration-Procedure-for-Summer-2027']::text[], '2026-11-13', '2026-11-13', TRUE),
('Darien YMCA School Age Camp', 'Darien YMCA', 'https://darien-ymca.org/child-care/summer-camp/school-age-camp/', NULL, NULL, '203-655-8228', '204 Hollow Tree Ridge Rd (Middlesex Middle School)', 'Darien', 'CT', '06820', 'Connecticut', 'day', ARRAY['sports','arts','STEM']::text[], NULL, ARRAY['Swimming lessons','Sailing','Canoeing','Paddle boards (Adventure & Pioneers groups)','Arts & crafts','STEM','Sports & games','Field trips','GaGa ball']::text[], NULL, NULL, NULL, 0, 7, 'A traditional co-ed day camp run by the Darien YMCA for children who have just finished kindergarten through 7th grade, with groups arranged by grade. Camp runs 8:30 AM–3:30 PM, and activities include swimming lessons, sailing, canoeing, arts and crafts, STEM, sports and field trips.', NULL, NULL, 444, 585, NULL, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, 'Includes swimming lessons, sailing and canoeing. Paddle boarding is only for the Adventure (finished grades 4–5) and Pioneers (finished grades 6–7) groups. The page does not say where the water activities take place.', NULL, NULL, 2026, '02c9b973-dc95-53ca-88dd-8d43a8fc10bb', 'darien-ymca-school-age-camp-darien', ST_GeogFromText('SRID=4326;POINT(-73.469 41.0776)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://darien-ymca.org/child-care/summer-camp/school-age-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Day Camps@The J (Summer@The J)', 'The Stamford JCC', 'https://www.stamfordjcc.org/daycampsatthej/', NULL, 'daycamps@stamfordjcc.org', '(203) 487-0973', '1035 Newfield Avenue', 'Stamford', 'CT', '06905', 'Connecticut', 'day', ARRAY['sports','arts','swimming','adventure']::text[], NULL, ARRAY['swimming','sports','STEAM','zip-lining','rock climbing','archery','boating','fishing','woodshop','cooking','gardening','music','field hockey','soccer','field trips','Shabbat programming']::text[], NULL, 3, NULL, NULL, 8, 'Day camp on the Stamford JCC''s 15-acre campus for children age 3 through grade 8, grouped as Chaverim (ages 3-4), Bonim (K-2), Tzofim (3-5) and Na''arim (6-8). Campers swim twice a day in a heated indoor pool and do sports, STEAM, zip-lining, rock climbing, archery, boating and fishing on the camp lake, with Jewish values and Shabbat woven in. Enrollment is a 2-week minimum.', NULL, 'Jewish', 1425, 7445, NULL, 'session', NULL, NULL, NULL, NULL, 'Full refund of tuition and deposit through January 31, and 50% through April 30, each minus a $50 processing fee. No refunds from May 1. A $100 security fee per camper is non-refundable.', NULL, NULL, NULL, NULL, 2027, '59b85320-618c-591e-8e71-29eab76cc793', 'day-camps-the-j-summer-the-j-stamford', ST_GeogFromText('SRID=4326;POINT(-73.5387 41.0534)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.stamfordjcc.org/clientuploads/DayCamps/DayCamps2027_EarlyBirdRates.pdf','https://www.stamfordjcc.org/daycampsatthej/','https://www.stamfordjcc.org/thedaycampexperience']::text[], '2026-11-13', '2026-11-13', TRUE),
('Early American Adventure Camp', 'Noah Webster House', 'https://noahwebsterhouse.org/summercamp/', 'https://docs.google.com/forms/d/e/1FAIpQLSc22JcHFOA60X02_hMguSO9KmrYxB7eLfrL4l1kGEs_CAvWCA/viewform?usp=publish-editor', 'education@noahwebsterhouse.org', '860-502-3247', '227 South Main Street', 'West Hartford', 'CT', '06107', 'Connecticut', 'day', ARRAY['academic','nature']::text[], NULL, ARRAY['Early American history','Historical chores','Period games','Hands-on crafts','Barnyard animal care','Vegetable gardening','Nature crafts']::text[], NULL, 8, 12, NULL, NULL, 'A full-day history camp for ages 8-12, run by the Noah Webster House museum with West Hartford''s Westmoor Park. Campers try 18th-century chores, games, and crafts, and at Westmoor Park they care for barnyard animals and tend a vegetable garden.', NULL, NULL, 290, 325, 325, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'b88de0eb-a102-5ed3-81fd-53f209eaf1f4', 'early-american-adventure-camp-west-hartford', ST_GeogFromText('SRID=4326;POINT(-72.7549 41.7666)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://noahwebsterhouse.org/summercamp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Explorers Adventure Full Day Camp', 'Stamford Museum & Nature Center', 'https://www.stamfordmuseum.org/child-youth/camp-programs/explorers-full-day-camp/', NULL, 'summercamp@stamfordmuseum.org', '203.977.6568', '39 Scofieldtown Road', 'Stamford', 'CT', '06903', 'Connecticut', 'day', ARRAY['nature','STEM']::text[], NULL, ARRAY['Farm experiences','Live animal handling','Gardening','Field studies','Nature trails and pond/stream exploration','Arts and crafts','Cooking','Laboratory science experiments','Animal care']::text[], NULL, NULL, NULL, 3, 7, 'A full-day nature and science camp, 9:00 am to 3:00 pm, for children entering grades 3–7. It meets at the Knobloch Family Farmhouse at the Stamford Museum & Nature Center. Each week has its own theme and mixes field studies, farm work, live animal handling, gardening, arts and crafts, and cooking, with no more than 14 campers per week.', NULL, NULL, 368, 460, 460, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '4d80db4f-c8c4-5163-9f91-4517f4ac9ce0', 'explorers-adventure-full-day-camp-stamford', ST_GeogFromText('SRID=4326;POINT(-73.5387 41.0534)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.stamfordmuseum.org/child-youth/camp-programs/explorers-full-day-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Flanders Nature Center Summer Camp & Academies', 'Flanders Nature Center & Land Trust', 'https://flandersnaturecenter.org/summer-camp-academies/', NULL, NULL, '(203) 263-3711', '596 Flanders Rd', 'Woodbury', 'CT', '06798', 'Connecticut', 'day', ARRAY['nature','arts','STEM']::text[], NULL, ARRAY['Nature exploration and hiking','Farm animal care','Arts and crafts','Theatre','Cooking','Environmental leadership','Survival skills','Science investigation (NGSS)']::text[], NULL, 3, 13, NULL, 8, 'Nature camps for ages 3 to 13 at Flanders Nature Center in Woodbury, run as half days (9am-1pm or 1-5pm) or all day (9am-5pm), with before care from 8am. Programs include nature exploration, farm animal care, art, cooking, youth environmental leadership and science academies.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, 'Cancel more than 4 weeks before your first camp day for a full refund, or 3 to 4 weeks before for a 50% refund. A 6.83% processing fee comes off both. There is no refund within 21 days of the start date, no pro-rating for missed days, and no refund if a camper is dismissed for behavior. If the camp cancels a session, families get a full refund or can transfer.', NULL, NULL, NULL, NULL, 2026, '3538b8a0-65df-58b6-bd3d-4e4da5095cb1', 'flanders-nature-center-summer-camp-and-academies-woodbury', ST_GeogFromText('SRID=4326;POINT(-73.2061 41.5616)'), TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://flandersnaturecenter.org/summer-camp-academies/','https://flandersnaturecenter.org/wp-content/uploads/2026/02/2026-Summer-Camp-At-a-Glance.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Guilford Art Center Summer Art for Kids + Teens', 'Guilford Art Center', 'https://guilfordartcenter.org', 'https://guilfordartcenter.org', 'info@guilfordartcenter.org', '203.453.5947', '411 Church Street', 'Guilford', 'CT', '06437', 'Connecticut', 'day', ARRAY['arts']::text[], NULL, ARRAY['ceramics','wheel throwing pottery','hand building clay','sewing','stained glass','metalsmithing','blacksmithing','beading','weaving','drawing','painting','mixed media','collage','sculpture','comics','character design','gallery visits']::text[], NULL, 5, NULL, NULL, NULL, 'Weekly half-day art classes for kids ages 5-12 and teens 13+, mostly 9am-12pm and 1-4pm. Combine a morning and an afternoon class with paid bridge care at midday to make a full day. Classes include ceramics, wheel pottery, sewing, metalsmithing, stained glass, blacksmithing, comics, drawing, painting and mixed media.', NULL, NULL, 180, 250, 225, 'week', TRUE, NULL, FALSE, TRUE, 'If GAC cancels a class, you get full tuition back or a credit toward another course. If you withdraw at least 2 weeks before the class starts, you get a full refund. If you withdraw up to 1 week before, you get a credit minus a $25 registration and materials fee; the credit is valid for one year. After that, there are no refunds or credits, and missed classes are not refunded.', 'Students with learning or social challenges are welcome. The center recommends talking with a staff member about your child''s needs beforehand.', NULL, NULL, NULL, 2026, '834a9b79-9238-5aa8-ab96-68aaf9cbbadd', 'guilford-art-center-summer-art-for-kids-teens-guilford', ST_GeogFromText('SRID=4326;POINT(-72.7061 41.339)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://guilfordartcenter.org/wp-content/uploads/2026/01/GAC-SummerYouth26.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Gymnastics Camp', 'Darien YMCA', 'https://darien-ymca.org/child-care/summer-camp/gymnastics-camp/', 'https://operations.daxko.com/Online/5010/Programs/search.mvc', NULL, '203.655.8228', '2420 Post Rd.', 'Darien', 'CT', '06820', 'Connecticut', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Gymnastics','Arts & crafts','Special activities']::text[], 'girls', NULL, NULL, 1, NULL, 'A girls-only half-day gymnastics camp (8:30 AM to 1:00 PM) in the Darien YMCA''s 11,000 sq ft gymnastics facility, with arts and crafts and special activities. Staff assess each gymnast and recommend a placement level in the YMCA Gymnastics Program at the end of camp. $375 a week for members, $457 for non-members.', NULL, NULL, 375, 457, NULL, NULL, NULL, NULL, NULL, TRUE, 'Cancel on or before April 1 for an online credit or refund less a $20 fee per week; after April 1 the fee is 20% per week. Check and credit card refunds carry an extra $20 processing fee.', 'Children with health or behavior concerns need an Individual Care Plan, shared with the camp directors, first aider and counselors as needed. Open to girls who have completed Kindergarten; Pre-K girls in the Y''s Pre-team (Team Dev and Level 2) program are also eligible.', NULL, NULL, NULL, 2026, 'b4f39e32-7a66-5f51-9304-7bcc25557909', 'gymnastics-camp-darien', ST_GeogFromText('SRID=4326;POINT(-73.469 41.0776)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://darien-ymca.org/about-us/financial-assistance/','https://darien-ymca.org/child-care/summer-camp/gymnastics-camp/','https://darien-ymca.org/child-care/summer-camp/school-age-camp/registration-details/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Hartford''s Camp Courant', 'Camp Courant, Inc.', 'https://campcourant.org', 'https://campcourant.org/parents/camp-registration-information/', NULL, '860-677-2355', '96 Batterson Park Road', 'Farmington', 'CT', '06032', 'Connecticut', 'day', ARRAY['general']::text[], NULL, ARRAY['swimming','arts and crafts','nature program and hikes','gardening','LEGO STEM','computer lab coding','photography','music and performing arts','sports and recreation','yoga','healthy choices','financial literacy','golf (First Tee)','deck hockey','Girl Scouts program','free dental screenings']::text[], NULL, 5, 12, NULL, NULL, 'A free summer day camp, 8:30am-3:30pm, for children ages 5-12 who live in Hartford or East Hartford, at a campsite in Farmington. Hartford campers pay only a $125 non-refundable application fee; East Hartford campers pay $200 a week. Buses from Hartford stops, free breakfast and lunch, a full-time nurse, swimming, arts, nature, STEM, music and sports.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, TRUE, 'The $125 application fee per camper per session is non-refundable.', 'A full-time nurse is on staff. In an emergency, campers go to the UConn Health Center, two minutes away.', 'Swimming and aquatics program teaches water safety and basic strokes; the camp publishes an Aquatics Safety Guide. Campers bring a bathing suit and towel, or the camp provides them.', NULL, NULL, 2026, '5c908a02-e393-5172-8fb5-917da5c03428', 'hartford-s-camp-courant-farmington', ST_GeogFromText('SRID=4326;POINT(-72.842 41.7298)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://campcourant.org/parents/camp-faqs/','https://campcourant.org/parents/camp-info/','https://campcourant.org/parents/camp-info/camp-programs/','https://campcourant.org/parents/camp-registration-information/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Hartford Stage Summer Studio Classes', 'Hartford Stage', 'https://www.hartfordstage.org/summer-studio-classes/', 'https://ticketing.hartfordstage.org/', 'elarson@hartfordstage.org', '(203) 908-1832', '359 Washington Street', 'Hartford', 'CT', '06106', 'Connecticut', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['Musical theatre','Acting','Voice','Choreography','Improvisation','Filmmaking','Technical theatre (scenic painting, props, costumes)','Story theater','Puppetry','Creative movement','Arts and crafts','Field trips','Broadway show trip (select programs)']::text[], NULL, 5, 18, NULL, NULL, 'Summer theatre programs for ages 5-18 run by Hartford Stage at the Greater Hartford Academy of the Arts, 9am-4pm: a teen musical, youth and junior musical productions, one-act plays, a children''s cast, a book-to-stage week, a filmmakers lab and a technical theater track. Most end in a performance or share day; older programs include a Broadway trip.', NULL, NULL, 430, 1720, NULL, 'session', TRUE, NULL, NULL, TRUE, 'Withdraw by May 1 for a full refund. From May 1 to June 1 you get a refund minus 20%. After June 1 there are no refunds unless the spot is filled, then a refund minus 20%.', 'Children with special needs and health conditions are welcome; disclose needs at registration. The program cannot provide 1-on-1 support, so a school aide or accommodation must be provided at the family''s expense. Contact the Studio Manager to discuss.', NULL, NULL, NULL, 2027, '58a653b9-2fc2-595c-b55b-d2d9fafb35ee', 'hartford-stage-summer-studio-classes', ST_GeogFromText('SRID=4326;POINT(-72.6851 41.7658)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=359+Washington+St&city=Hartford&state=CT&benchmark=Public_AR_Current&format=html','https://www.hartfordstage.org/summer-studio-classes/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Incarnation Camp', NULL, 'https://incarnationcamp.org/', 'https://incarnationcamp.campbrainregistration.com/', 'info@incarnationcamp.org', '(860) 767-0848', '253 Bushy Hill Road', 'Ivoryton', 'CT', '06442', 'Connecticut', 'sleepaway', ARRAY['general','outdoor']::text[], NULL, ARRAY['Swim instruction','Canoeing','Sailing','Water trampoline and iceberg','Rope swing','Corcl boats','Water slide','Land activities','Evening programming','Special events','Camp-outs','Horseback riding (extra cost)','Pioneer Village 5-day hike, bike and canoe trips (ages 14-15)','Open-fire cooking (Pioneer Village)']::text[], NULL, 7, 15, NULL, NULL, 'Nonprofit overnight camp for ages 7-15 on a 740-acre wooded property with a private, spring-fed lake in Ivoryton, CT. Campers live in platform tents and come for 2, 4 or 6 weeks. Campers 14-15 join Pioneer Village, the teen program, with cooking over a fire and 5-day hike, bike or canoe trips.', NULL, NULL, 2999, 7799, NULL, NULL, NULL, TRUE, TRUE, TRUE, 'No refund if a camper is sent home for behavior or withdrawn early. If a camper is too ill or contagious to stay, a pro-rated fee is negotiated, and a doctor''s note may be required.', NULL, 'Swimming and boating on the camp''s own 1.3-mile spring-fed lake, with no motorboats. Waterfront staff and counselors are American Red Cross lifeguard trained; swim classes for all abilities.', NULL, NULL, 2027, 'b92ecd00-a068-5af5-abdc-48eafe6f2780', 'incarnation-camp-ivoryton', ST_GeogFromText('SRID=4326;POINT(-72.4134 41.3499)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://incarnationcamp.org/contact-us','https://incarnationcamp.org/dates-rates','https://incarnationcamp.org/faq','https://incarnationcamp.org/pv','https://incarnationcamp.org/waterfront']::text[], '2026-11-13', '2026-11-13', TRUE),
('JCC Day Camps', 'JCC of Greater New Haven', 'https://jccnh.org/daycamps', NULL, 'webmaster@jccnh.org', '(203) 387-2424', '360 Amity Rd.', 'Woodbridge', 'CT', '06525', 'Connecticut', 'day', ARRAY['general']::text[], NULL, ARRAY['Swimming and swim lessons','Arts and crafts','Drama','Music and dance','STEAM / MakerSpace','Low ropes course','Archery','Sports','Basketball','Volleyball','Ga-ga','Hiking','Israel Day and Jewish values activities','Community service and tzedakah projects']::text[], NULL, 4, NULL, NULL, 9, 'Day camp for age 4 through grade 9 on the JCC of Greater New Haven''s 54-acre Woodbridge campus, with an outdoor pool, low ropes course, archery, sports fields, a stage and four miles of trails. Two 4-week sessions, Monday to Friday 9 AM to 4 PM, with after-camp enrichment. Based on Jewish values and open to all.', NULL, 'Jewish', NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, NULL, NULL, 'Outdoor pool. Campers age 4 through grade 5 get swim lessons 4 days a week plus free swim; older campers have free swim only.', NULL, NULL, 2027, '6208d7f8-8a09-5a62-9c0b-7e757d48ed5b', 'jcc-day-camps-woodbridge', ST_GeogFromText('SRID=4326;POINT(-73.0048 41.3537)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://jccnh.org/camp/faq','https://jccnh.org/camp/our-facilities','https://jccnh.org/daycamps','https://www.jccnh.org/camp/dates-rates']::text[], '2026-11-13', '2026-11-13', TRUE),
('Longshore Sailing School Junior Programs', 'Longshore Sailing School', 'https://www.longshoresailing.com/core', 'https://app.amilia.com/store/en/longshore-sailing-school/shop/programs', 'info@longshoresailingschool.com', '203-226-4646', '260 Compo Road South', 'Westport', 'CT', '06880', 'Connecticut', 'specialty', ARRAY['sailing']::text[], NULL, ARRAY['Sailing','Catamaran sailing','Sailboat racing','Kayaking','Stand-up paddleboarding','Swimming breaks']::text[], NULL, 8, 16, NULL, NULL, 'Community sailing school at the mouth of the Saugatuck River in Westport, open to the public. Half-day junior programs for ages 8-16: a learn-to-sail curriculum (Sailing 1 to 4, one or two weeks), catamaran and racing courses, and one-week kayaking, paddleboarding and catamaran adventure weeks. Swimming ability required.', NULL, NULL, 450, 1100, 500, 'session', NULL, NULL, NULL, NULL, 'Full refund minus a 4% fee if you cancel 21 or more days before the course starts. No refunds or transfers within 21 days of the start date, and no refunds or credits for missed classes, illness included. No refunds if LSS closes at the request of the Town of Westport.', NULL, 'Swim test on the first day of class, held in the pool next to the facility. Junior students must bring their own Type III lifejacket. Classes go on the water in the rain. If lightning, thunder or heavy wind keeps them off the water, the school stays open to look after students.', NULL, NULL, 2027, '9331e261-5daa-50dd-b7a1-945c6481d40f', 'longshore-sailing-school-junior-programs-westport', ST_GeogFromText('SRID=4326;POINT(-73.3579 41.1415)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://app.amilia.com/store/en/longshore-sailing-school/shop/programs','https://www.longshoresailing.com/','https://www.longshoresailing.com/core','https://www.longshoresailing.com/junior-adventure-programs','https://www.longshoresailing.com/program-faqs']::text[], '2026-11-13', '2026-11-13', TRUE),
('Music Theatre of Connecticut Summer Theatre Programs', 'Music Theatre of Connecticut', 'https://www.musictheatreofct.com/school-summer', 'https://www.musictheatreofct.com/register', 'admin@musictheatreofct.com', '(203) 454-3883', '509 Westport Ave', 'Norwalk', 'CT', '06851', 'Connecticut', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['Musical theatre','Acting','Singing','Dancing','Improvisation','Puppetry','Master classes','Performances']::text[], NULL, NULL, NULL, 2, 12, 'Musical theatre summer programs at Music Theatre of Connecticut in Norwalk. One-week half-day or full-day workshops for grades 2 to 8 rehearse a Broadway "show of the week" and perform it in the evening after the last rehearsal. A two-week production for grades 6 to 12 puts on an abridged 1.5-hour musical.', NULL, NULL, 625, 1225, 925, 'week', NULL, NULL, FALSE, TRUE, '$200 of tuition is non-refundable, and there are no refunds from April 1. Full policies are on the MTC Policies page.', NULL, NULL, NULL, NULL, 2026, 'f034663f-9895-59e6-9ad3-93201361dcff', 'music-theatre-of-connecticut-summer-theatre-programs-norwalk', ST_GeogFromText('SRID=4326;POINT(-73.4198 41.0927)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.musictheatreofct.com/register','https://www.musictheatreofct.com/school-summer']::text[], '2026-11-13', '2026-11-13', TRUE),
('NESS Summer Camp Programs', 'New England Science & Sailing (NESS)', 'https://nessf.org/experiential-learning/youth-programs/summer/', 'https://campscui.active.com/orgs/NESS?season=3768746', 'adventure@nessf.org', '860.535.9362', '72 Water Street', 'Stonington', 'CT', '06378', 'Connecticut', 'day', ARRAY['sailing','nature','STEM','sports']::text[], NULL, ARRAY['Sailing','Marine science','Fishing','Surfing','Stand-up paddleboarding','Kayaking','Snorkeling','Powerboating','Windsurfing','Boater''s education']::text[], NULL, 4, 17, NULL, NULL, 'Weekly half-day summer programs for ages 4 to 17 at New England Science & Sailing on Stonington Harbor: sailing from first Optimist lessons to 420 and Laser racing, marine science, fishing, surfing and mixed adventure sports. Children can take a morning and an afternoon program with a supervised lunch in between.', NULL, NULL, 260, 385, NULL, 'week', NULL, NULL, FALSE, TRUE, NULL, NULL, 'Programs run on Stonington Harbor and Long Island Sound. Campers don''t need to be skilled swimmers but must be comfortable on and around the water. Everyone wears a life jacket on the water; for some activities older campers can take a swim check with a certified lifeguard to go without one.', NULL, NULL, 2026, '073195ff-c643-5aa3-a642-b850b5e55359', 'ness-summer-camp-programs-stonington', ST_GeogFromText('SRID=4326;POINT(-71.9114 41.3635)'), TRUE, FALSE, FALSE, TRUE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://nessf.org/experiential-learning/youth-programs/summer/','https://nessf.org/ness-summer-camp-programs-2026/']::text[], '2026-11-13', '2026-11-13', TRUE),
('New Canaan Nature Center Summer Camp', 'New Canaan Nature Center', 'https://newcanaannature.org/summer-camp-updated/', NULL, 'camp@newcanaannature.org', '(203) 966-9577 x1041', '144 Oenoke Ridge', 'New Canaan', 'CT', '06840', 'Connecticut', 'day', ARRAY['nature']::text[], NULL, ARRAY['Forest exploration','Insect and bug study','Plant and garden exploration','Birds of prey and birdwatching','Fossils and soil exploration','Rock exploration','Pond exploration','Shelter and fort building','Animal ambassadors','Recycling projects','Water play and slip and slides']::text[], NULL, 3, NULL, NULL, 8, 'Outdoor nature day camp on the New Canaan Nature Center''s 40 acres of ponds, fields and forest, with a new theme each week. Half day (9am to noon) for ages 3 and 4, full day (9am to 3:30pm) from the 4s and 5s through 5th grade, and an Adventure Camp for grades 6 to 8 with daily off-site trips and a Thursday cookout until 7pm.', NULL, NULL, 385, 640, 545, 'week', NULL, NULL, NULL, TRUE, '75% refund for cancellations before May 15, 2026; no refunds after that. Changing or swapping weeks costs $25. Illness or family emergencies are handled case by case.', NULL, NULL, NULL, NULL, 2026, 'dabb5a58-17fb-5ce5-8895-33c40fbacf8b', 'new-canaan-nature-summer-camp', ST_GeogFromText('SRID=4326;POINT(-73.4951 41.1468)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://newcanaannature.org/summer-camp-updated/','https://newcanaannature.org/wp-content/uploads/2026/01/2026-adventure-camp-brochure_draft1.pdf','https://newcanaannature.org/wp-content/uploads/2026/01/2026-themes-summer-camp.pdf','https://newcanaannature.org/wp-content/uploads/2026/04/2026-summer-program-refund-policy.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Norma F. Pfriem Summer Day Camp', 'Cardinal Shehan Center', 'https://www.shehancenter.org/programs/summer-day-camp/', NULL, NULL, '(203) 336-4468', '1494 Main Street', 'Bridgeport', 'CT', '06604', 'Connecticut', 'day', ARRAY['sports','arts','STEM','performing_arts','academic']::text[], NULL, ARRAY['swimming','arts and crafts','photography','computers','music','basketball','field sports','tennis','performing arts','health and fitness','dance','math','STEM','literacy','field trips']::text[], NULL, NULL, NULL, NULL, NULL, 'A weekly summer day camp at the Shehan Center in Bridgeport that mixes sports, swimming, arts and performing arts with math, STEM and literacy classes, plus special events and field trips.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Swimming is one of the camp activities, using the Shehan Center''s own facilities. The page gives no pool or supervision details.', NULL, NULL, 2026, '3895fc04-0c78-5615-8bc3-15cb0c8bff38', 'norma-f-pfriem-summer-day-camp-bridgeport', ST_GeogFromText('SRID=4326;POINT(-73.1958 41.1874)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.shehancenter.org/programs/summer-day-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('North Haven Recreation Summer Day Camp', 'North Haven Department of Recreation', 'https://www.northhaven-ct.gov/government/town_departments/departments_(m_-_r)/recreation/summer_brochure_2023.php', NULL, 'Rec@northhaven-ct.gov', '(203) 239-5321 ext. 8530', '7 Linsley Street', 'North Haven', 'CT', '06473', 'Connecticut', 'day', ARRAY['general']::text[], NULL, ARRAY['Cooperative games','Arts and crafts','Reading program','Weekly special events','Pizza Day Fridays']::text[], NULL, 3, 13, NULL, NULL, 'The town of North Haven''s summer day camp for ages 3 to 13 at the Wakeley Community & Recreation Center, 8am to 5pm on weekdays. Each week has a theme with cooperative games, arts and crafts, a reading program and a special event, and ends with Pizza Day. Non-residents can join for $10 more a week.', NULL, NULL, 250, 310, 310, 'week', NULL, NULL, NULL, NULL, 'No refunds unless the department cancels the program, your place can be filled by another registration, or you provide a physician''s note.', 'The Recreation Department welcomes participants with disabilities and makes reasonable accommodations under the ADA. Ask at registration, at least two weeks before the program starts.', NULL, NULL, NULL, 2026, '8dbbdc83-0452-56ac-af0f-d19a4cd4fd3f', 'north-haven-recreation-summer-programs-north-haven', ST_GeogFromText('SRID=4326;POINT(-72.8564 41.3815)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.northhaven-ct.gov/government/town_departments/departments_(m_-_r)/recreation/summer_brochure_2023.php']::text[], '2026-11-13', '2026-11-13', TRUE),
('Renbrook School Summer Adventure', 'Renbrook School', 'https://www.renbrook.org/summer/', 'https://renbrook.campintouch.com/ui/forms/application/camper/App', NULL, '860-236-1661', '2865 Albany Avenue', 'West Hartford', 'CT', '06117', 'Connecticut', 'day', ARRAY['arts','STEM','nature','academic','sports']::text[], NULL, ARRAY['swimming','archery','ropes courses','rocketry','cooking','ceramics','woodworking']::text[], NULL, 3, NULL, NULL, 9, 'A day camp at Renbrook School in West Hartford for children age 3 through Grade 9, led by teachers and educators. Summer 2027 runs June 14 to July 30: a one-week Pre-Season Camp (June 14-17), then three two-week sessions. Registration for 2027 is open.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, 'Each session includes a non-refundable $75 registration fee. The rest of tuition is refundable until May 1, 2027, when payment in full is due.', NULL, 'All campers swim every day. Lessons follow the American Red Cross Learn to Swim program at about one staff member per four campers, with a placement test on day one. Three fenced pools (two 2.5 feet deep, one 3.5 to 8 feet) each have a Red Cross lifeguard on duty; floaties are not allowed.', NULL, NULL, 2027, '8176e24c-d81c-5bdc-af55-a21410c907b1', 'renbrook-school-summer-adventure-west-hartford', ST_GeogFromText('SRID=4326;POINT(-72.7549 41.7666)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.renbrook.org/summer/','https://www.renbrook.org/summer/camp-programs/life-at-the-pool/','https://www.renbrook.org/summer/general-info/before-and-after-camp-care/','https://www.renbrook.org/summer/general-info/campership/','https://www.renbrook.org/summer/general-info/dates-and-rates/','https://www.renbrook.org/summer/general-info/pre-season-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Roaring Brook Nature Center Summer Discovery Days', 'The Children''s Museum Inc.', 'https://roaringbrook.org/summer-2027-discovery-days/', 'https://purchase.thechildrensmuseumct.org/calendar.aspx', NULL, '860-693-0263', '70 Gracey Road', 'Canton', 'CT', '06019', 'Connecticut', 'day', ARRAY['nature']::text[], NULL, ARRAY['Hikes','Games','Stories','Crafts','Animal visits','Stream and pond exploration']::text[], NULL, 4, NULL, NULL, NULL, 'Weekly themed nature programs at Roaring Brook Nature Center in Canton, in four age groups from Acorns (ages 4 to 5) to Oaks (grades 4 and up). Each week brings hikes, games, stories, crafts and visits with the center''s animals. Summer 2027 dates and themes will be posted in early 2027.', NULL, NULL, 270, 315, 315, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'e17aeb06-57e6-5568-af79-74bac4323883', 'roaring-brook-nature-center-summer-discovery-days', ST_GeogFromText('SRID=4326;POINT(-72.9109 41.8587)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://roaringbrook.org/summer-2027-discovery-days/','https://www.thechildrensmuseumct.org/summer-2026-discovery-days/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Sails & Trails Camp', 'Quassapaug Sailing Center', 'https://www.qsailingcenter.org/sailsandtrails', 'https://theclubspot.com/register/camp/RgkIiNDs5y/class', 'SailsAndTrails@qsailingcenter.org', '203-758-2241', NULL, 'Middlebury', 'CT', '06762', 'Connecticut', 'day', ARRAY['sports','nature']::text[], NULL, ARRAY['Sailing (Optimist dinghies)','Sailing (420 dinghies)','Kayaking','Hiking','Animal tracking','Scavenger hunts','Fishing','Wetland exploration','Intro to racing']::text[], NULL, 9, 16, NULL, NULL, 'Full-day (9am-4pm) camp on Lake Quassapaug, run in two-week sessions. Children can pick sailing plus nature exploration in Flanders'' Whittemore Sanctuary (Sails & Trails), or a sailing-only program in Optimist dinghies (ages 9-12) or 420 dinghies (ages 12-16).', NULL, NULL, 480, 690, NULL, 'session', TRUE, NULL, FALSE, TRUE, 'No refunds for camp registrations, except when camp is cancelled because of COVID-related government restrictions. Families registered for the cancelled 2026 Session 4 were offered a transfer or a refund.', NULL, 'Campers sail and kayak on Lake Quassapaug. They must be comfortable swimming in a life jacket, and there is a swim test (done in a life jacket). Life jackets (Type III USCG approved, non-inflatable) must be worn at all times on or near the water. QSC provides them, but campers may bring their own.', NULL, NULL, 2026, 'c3ad8911-dced-5083-8eb8-00df6ae7ccb5', 'sails-and-trails-camp-middlebury', ST_GeogFromText('SRID=4326;POINT(-73.123 41.5247)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://www.qsailingcenter.org/sailsandtrails']::text[], '2026-11-13', '2026-11-13', TRUE),
('SJ Riding Camp – Day Camp', 'SJ Riding Camp', 'https://sjridingcamp.com/day-camp/', 'https://sjriding.campintouch.com/ui/forms/application/camper/App', 'camp@sjridingcamp.com', '860-872-4742', '130 Sandy Beach Rd', 'Ellington', 'CT', '06029', 'Connecticut', 'day', ARRAY['sports']::text[], NULL, ARRAY['Horseback riding','Learning about animals','Residential camp daytime activities']::text[], NULL, 8, 13, NULL, NULL, 'Horseback riding day camp in Ellington for ages 8 to 13 who are ready for the residential camp''s activities but not for staying overnight. Day campers join the overnight campers'' daytime schedule, Monday to Friday 8:30am to 6pm, with two rides a day.', NULL, NULL, 975, 975, 975, 'week', NULL, NULL, TRUE, NULL, 'The balance, less the deposit, is refunded only if you cancel by May 1, 2027. No refunds for leaving camp early for any reason. Session changes depend on space.', NULL, NULL, NULL, NULL, 2026, '43c8a708-5cb2-5878-b255-76d9991c1c30', 'sj-riding-camp-day-camp-ellington', ST_GeogFromText('SRID=4326;POINT(-72.4456 41.9141)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://sjridingcamp.com/day-camp-dates-rates/','https://sjridingcamp.com/day-camp/','https://sjridingcamp.com/frequently-asked-questions/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Art Studios', 'Silvermine Arts Center', 'https://www.silvermineart.org', 'https://www.silvermineart.org', 'schoolregistrar@silvermineart.org', '203-966-9700, ext. 110', '1028 Silvermine Rd', 'New Canaan', 'CT', '06840', 'Connecticut', 'specialty', ARRAY['arts']::text[], NULL, ARRAY['Ceramics','Printmaking','Drawing','3-D Art','Painting','Glass Flame Working','Comics','Photography','Jewelry','Mixed Media & Collage','Digital Arts','Pre-K Process Art']::text[], NULL, 3, 17, NULL, NULL, 'Week-long art classes for ages 3-17 at Silvermine Arts Center, with morning and afternoon sessions that can be combined for a full day. Media include ceramics, printmaking, drawing, painting, glass flame working, comics, photography, jewelry, digital arts and Pre-K process art.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Full refund less the $35 registration fee for withdrawals by May 1, 2026; credit only from May 2 until 14 days before camp; no refund or credit within 14 days of the start. Withdrawals by phone only.', NULL, NULL, NULL, NULL, 2026, 'f7a684d2-f703-5860-8f12-19a5eccd0b1c', 'summer-art-studios-new-canaan', ST_GeogFromText('SRID=4326;POINT(-73.4951 41.1468)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.silvermineart.org','https://www.silvermineart.org/wp-content/uploads/2026/01/Summer-Art-Policies-PDF-1-7-26.pdf','https://www.silvermineart.org/wp-content/uploads/2026/01/Summer-Art-Studios-Catalog-2026-Final-sm.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer at Hopkins', 'Hopkins School', 'https://www.hopkins.edu/academics/summer-at-hopkins', NULL, 'summerschool@hopkins.edu', '(203) 397-1001', '986 Forest Road', 'New Haven', 'CT', '06515', 'Connecticut', 'day', ARRAY['academic']::text[], NULL, ARRAY['Academic courses for credit and enrichment','Language arts','Math','Robotics','Dungeons & Dragons']::text[], NULL, NULL, NULL, 5, 12, 'Hopkins School''s summer school in New Haven offers small academic and enrichment classes for students entering grades 5 to 12, from Hopkins and other schools. Classes run in two-hour blocks in the morning and early afternoon, and families pay per course.', NULL, NULL, 800, 3700, NULL, 'course', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '07ea99e7-f2cf-5c6a-b90a-3848371c3af7', 'summer-at-hopkins-new-haven', ST_GeogFromText('SRID=4326;POINT(-72.9251 41.3082)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.hopkins.edu/academics/summer-at-hopkins','https://www.hopkins.edu/academics/summer-at-hopkins/summer-school-2026','https://www.hopkins.edu/academics/summer-at-hopkins/summer-school-2026/lower-school','https://www.hopkins.edu/academics/summer-at-hopkins/summer-school-2026/middle-school','https://www.hopkins.edu/academics/summer-at-hopkins/summer-school-2026/upper-school']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Camp at Fairfield Nature Center', 'The Connecticut Audubon Society', 'https://ctaudubon.org/locations/the-fairfield-nature-center-and-larsen-sanctuary/summer-camp/', NULL, 'tkevalis@ctaudubon.org', '203-259-6305, x117', '2325 Burr Street', 'Fairfield', 'CT', '06824', 'Connecticut', 'day', ARRAY['nature']::text[], NULL, ARRAY['Outdoor nature exploration','Wetland exploration','Bike Camp','Travel Adventure Camp (completed 6th-7th grade)','Counselor in Training (ages 14-18)']::text[], NULL, 4, 18, NULL, 7, 'Weekly outdoor nature day camp at the Connecticut Audubon Society''s Fairfield Nature Center, with small groups for ages 4 through completed 7th grade and a Counselor-in-Training program for ages 14-18. Sessions run outdoors rain or shine.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Optional Registration Protection can be bought at checkout and gives a full refund for specified reasons such as illness, injury or work relocation. Without it, requests must be made by email. Changes must be requested at least two weeks before the session. Cancellations before June 1 are refunded minus a 20% fee per program, and membership fees are not refunded. There are no refunds after June 1. If the camp cancels a program, you get a full refund.', 'There is an Individual Plan of Care form, and staff are trained in first aid, CPR and EpiPen use.', NULL, NULL, NULL, 2026, 'f051dd0c-ce04-532c-901c-160051cef172', 'summer-camp-at-fairfield-nature-center-fairfield', ST_GeogFromText('SRID=4326;POINT(-73.2637 41.1418)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://ctaudubon.org/locations/the-fairfield-nature-center-and-larsen-sanctuary/summer-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Camp at Milford Point (Coastal Center Summer Camps)', 'The Connecticut Audubon Society', 'https://ctaudubon.org/locations/the-coastal-center-at-milford-point-and-smith-hubbell-sanctuary/summer-camp/', NULL, 'milford@ctaudubon.org', '203-878-7440', '1 Milford Point Road', 'Milford', 'CT', '06460', 'Connecticut', 'day', ARRAY['nature','STEM']::text[], NULL, ARRAY['beach exploration','marsh exploration','woodlands exploration','gardens','nature-based arts and crafts','hands-on experiments','animal meet-and-greets','games','community science']::text[], NULL, NULL, NULL, 0, 5, 'A weekly nature day camp at Connecticut Audubon''s Coastal Center in Milford for children who have completed grades K-5. Campers explore the beach, marsh, woodlands and gardens and do nature crafts, experiments and games, with a new theme each week.', NULL, NULL, 316, 395, 395, 'week', NULL, NULL, NULL, NULL, 'You can buy optional Registration Protection at checkout, which gives a full refund for specified reasons such as illness or injury. Without it, requests must be made by email at least two weeks before the session. Cancellations before June 1 are refunded minus a 20% fee per program, and membership fees are not refunded. There are no refunds after June 1. If the camp cancels a program, you get a full refund.', 'There is an Individual Plan of Care form for children who need medication or special care. Staff are trained in first aid, CPR and EpiPen use.', 'Includes water habitat explorations, but no swimming.', NULL, NULL, 2026, '800eb363-0380-5113-8f14-8be93d6bc8ff', 'summer-camp-at-milford-point-coastal-center-summer-camps-milford', ST_GeogFromText('SRID=4326;POINT(-73.0573 41.2223)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://ctaudubon.org/locations/the-coastal-center-at-milford-point-and-smith-hubbell-sanctuary/summer-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer of STEM Adventures', 'Talcott Mountain Science Center', 'https://talcottscience.org/summer/', 'https://campscui.active.com/orgs/TMSC?orglink=camps-registration', 'summer@tmsc.org', '860-677-8571', '324 Montevideo Rd', 'Avon', 'CT', '06001', 'Connecticut', 'day', ARRAY['STEM','technology','nature']::text[], NULL, ARRAY['Robotics (LEGO SPIKE Prime)','Coding and app design','3D printing','Claymation and computer animation','Game design','Planetarium shows','Marine science','Paleontology','Dissections','Arduino and Raspberry Pi','Geocaching','Field trips','Camp Invention']::text[], NULL, 5, NULL, 0, 8, 'Week-long, hands-on STEM programs for rising K-8 students on Talcott Mountain in Avon, CT. Each week offers different classes (robotics, coding, marine science, paleontology and more) grouped into K-2, 3-5 and 6-8 grade bands, and some include field trips.', NULL, NULL, 515, 675, 625, 'week', FALSE, TRUE, FALSE, NULL, 'More than two weeks before the start: full credit or a 90% refund. Between two weeks and two business days before: 50% refund or credit. Less than two business days before: no refund. No refunds for days missed through illness.', 'Children with special needs are welcome if they can follow the behavior policy, are toilet trained and can follow spoken instructions. Families may bring their own paraprofessional; the center cannot provide aides. A nut-free table is set up at snack and lunch.', NULL, NULL, NULL, 2026, '5ef6e15c-d4d9-56de-bb8c-9ba9c296ce8f', 'summer-of-stem-adventures-avon', ST_GeogFromText('SRID=4326;POINT(-72.852 41.7872)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://talcottscience.org/summer/','https://talcottscience.org/summer/summer-policies','https://talcottscience.org/summer/transportation/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Winding Trails Summer Camp', 'Winding Trails', 'https://windingtrails.org', 'https://windingtrails.org/camp', NULL, '(860) 677-8458', '50 Winding Trails Drive', 'Farmington', 'CT', '06032', 'Connecticut', 'day', ARRAY['general','outdoor','sports']::text[], NULL, ARRAY['Archery','Arts & Crafts','Baseball','Basketball','Boating','Climbing Tower','Cooperative Games','Dance','Drama','Fishing','Fort Building','Gaga','Giant Slide','High Ropes','Low Ropes','Mountain Biking','Music','Nature','Orienteering','Sailing (grades 6-8, extra fee)','Soccer','Softball','Street Hockey','Swimming','Tennis','Volleyball']::text[], NULL, 3, NULL, 0, 8, 'A day camp running Monday to Friday in four two-week sessions. The full-day camp (9:00am–3:15pm) is for children entering kindergarten through eighth grade. A half-day camp (9:00am–1:45pm) is for 3- and 4-year-olds.', NULL, NULL, 575, 835, NULL, 'session', TRUE, TRUE, NULL, TRUE, 'Each child must pay a $200 deposit per session. The deposit cannot be refunded or transferred and is taken off the balance due. Full payment is due by each session''s deadline (April 26, May 10, May 24 and June 7). After a deadline has passed, the only refunds are for a camper who misses at least 3 days in a row because of illness or injury that happened at camp, and a physician''s note is required.', NULL, NULL, NULL, NULL, 2027, '3b088a42-54cd-5355-9c87-9181d46c50f2', 'winding-trails-summer-camp', ST_GeogFromText('SRID=4326;POINT(-72.842 41.7298)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://windingtrails.org/camp-age-groups-and-activities','https://windingtrails.org/contact-us','https://windingtrails.org/hours-directions-maps','https://windingtrails.org/session-dates-and-fees']::text[], '2026-11-13', '2026-11-13', TRUE),
('Woodbridge Recreation Summer Camp', 'Woodbridge Recreation Department', 'https://www.woodbridgect.org/292/Summer-Camp', NULL, 'recreation@woodbridgect.org', '203-389-3446', 'Beecher Road School, 40 Beecher Rd.', 'Woodbridge', 'CT', '06525', 'Connecticut', 'day', ARRAY['arts','performing_arts','sports']::text[], NULL, ARRAY['Arts and Crafts','Drama','Music','Game Room','Athletics']::text[], NULL, NULL, NULL, 0, 8, 'A half-day town recreation camp for grades K-8 at Beecher Road School, running 9 a.m. to noon on weekdays. The day is split into 45-minute periods of arts and crafts, drama, music, game room and athletics.', NULL, NULL, 500, 1100, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'f4efe4f6-d322-5ac3-8df3-24fc92c99b70', 'woodbridge-recreation-summer-camp-woodbridge', ST_GeogFromText('SRID=4326;POINT(-73.0048 41.3537)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=40+Beecher+Rd&city=Woodbridge&state=CT&benchmark=Public_AR_Current&format=html','https://www.woodbridgect.org/292/Summer-Camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Woodcock Nature Center Summer Nature Camp', 'Woodcock Nature Center', 'https://www.woodcocknaturecenter.org/summercamp', 'https://www.ultracamp.com/info/upcomingSessions.aspx?idCamp=1258&campCode=WNC&lnkCategory=Summer+Camp', 'wnc@woodcocknaturecenter.org', '(203) 762-7280', '56 Deer Run Road', 'Wilton', 'CT', '06897', 'Connecticut', 'day', ARRAY['nature','outdoor']::text[], NULL, ARRAY['Live animal encounters','Nature crafts','Hiking','Kayaking','Wilderness skills','Stream exploration','Scavenger hunts','Obstacle courses','Wilderness games','Experiments','Nature art']::text[], NULL, 4, NULL, NULL, 8, 'A weekday nature day camp (9:30 am to 3 pm) on a 150-acre preserve in Wilton, CT, for children entering PreK through 8th grade. Environmental educators lead animal encounters, nature crafts, hiking, boating on the pond and wilderness skills.', NULL, NULL, 530, 570, 530, 'week', NULL, NULL, FALSE, TRUE, NULL, NULL, 'The camp page mentions kayaking on the center''s pond; the program pages mention canoeing on the pond and wading in streams and wetlands. No swimming is mentioned, and no supervision or swim test details are given.', NULL, NULL, 2026, 'a1090767-73db-5194-ab29-c520bf1465c5', 'woodcock-nature-center-summer-nature-camp-wilton', ST_GeogFromText('SRID=4326;POINT(-73.4379 41.1951)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.woodcocknaturecenter.org/campprograms','https://www.woodcocknaturecenter.org/summercamp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Woodruff Family YMCA Camp Wepawaug', 'Central Connecticut Coast YMCA', 'https://cccymca.org/locations/woodruff/', 'https://ymcaccc.sgasoftware.com/Sales/Public', 'infomilford@cccymca.org', '203-878-6501', '631 Orange Avenue', 'Milford', 'CT', '06461', 'Connecticut', 'day', ARRAY['general','sports']::text[], NULL, ARRAY['Swimming (daily)','Gaga','Ropes course','Rock wall','STEM','Archery','Arts and crafts','Weekly theme activities','Specialty camps: STEAM, Archery, Creative Crafts, Challenge Camp']::text[], NULL, NULL, NULL, 0, 9, 'The Woodruff Family YMCA''s summer day camp, Camp Wepawaug, on 20 acres in Milford for children entering kindergarten through 9th grade. Campers swim every day and do gaga, ropes and rock wall, STEM, archery and arts and crafts, with weekly themes. Camp runs 9:00 to 3:30 with pre and post care.', NULL, NULL, 219, 399, 322, 'week', TRUE, NULL, NULL, TRUE, 'A $50 deposit per camper per week is due at registration and cannot be refunded or transferred.', 'The Y works with children of all abilities. Families of a child who needs social, behavioral or medical accommodations are asked to contact the Camp Director.', 'Campers swim every day. The brochure gives no swim test or pool details.', TRUE, 'https://cccymca.org/wp-content/uploads/WDF-2026-Summer-Camp-Brochure-Compressed-2.pdf', 2026, '74de9d43-6343-5d70-aa49-684166d19085', 'woodruff-family-ymca-summer-day-camp-milford', ST_GeogFromText('SRID=4326;POINT(-73.0573 41.2223)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://cccymca.org/locations/woodruff/','https://cccymca.org/wp-content/uploads/WDF-2026-Summer-Camp-Brochure-Compressed-2.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('YMCA Camp Mohawk', 'YMCA Camp Mohawk', 'https://www.campmohawk.org', 'https://ymcacampmohawk.campintouch.com/ui/forms/application/camper/App', 'info@campmohawk.org', '(860) 672-6655', '246 Great Hill Road', 'Litchfield', 'CT', '06759', 'Connecticut', 'sleepaway', ARRAY['general','sports','arts']::text[], NULL, ARRAY['Swimming','Canoeing','Kayaking','Sailing','Rowing','Windsurfing','Stand up paddleboarding','Log rolling','Fishing (11+)','Archery','Tennis','Soccer','Field hockey','Basketball','Volleyball','Yoga','Dance','Cheerleading','Tumbling','Ropes course (11+)','Nature','Outdoor living','Arts and crafts','Ceramics','Drama production','Chorus','Ukulele (11+)','Baking','Sewing and design','Farm and animal care','Horseback riding lessons (extra fee)']::text[], 'girls', 5, 17, NULL, NULL, 'A YMCA camp for girls in Litchfield, CT, on its own pond. Overnight camp runs in two-week sessions for ages 7-15 and one-week sessions mostly for ages 7-11; there is also a weekly day camp for ages 5-12 and a four-week Counselor in Training program for ages 16-17. Horseback riding lessons can be added for an extra fee.', NULL, NULL, 483, 3150, 1646, 'week', NULL, TRUE, TRUE, TRUE, 'Overnight camp: a $300 deposit per session is not refundable; cancellations in writing before April 1 get all other fees back, and there are no refunds after April 1 or once camp has started. Day camp: an $80 deposit per week is not refundable; cancellations before June 1 get all other fees back, none after. Deposits move with the camper if she switches to a session with space.', NULL, 'Waterfront activities are on Mohawk Pond, which camp has to itself: instructional and free swimming, canoeing, kayaking, rowing, sailing, windsurfing, paddleboarding and log rolling. Day campers have a daily free swim and waterfront period.', NULL, NULL, 2027, '7073d63a-85f4-5fa6-ad6e-6fe83fb893c0', 'ymca-camp-mohawk-litchfield', ST_GeogFromText('SRID=4326;POINT(-73.1928 41.7409)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.campmohawk.org/activities','https://www.campmohawk.org/dates-rates','https://www.campmohawk.org/daycamp','https://www.campmohawk.org/directions','https://www.campmohawk.org/refund-policy']::text[], '2026-11-13', '2026-11-13', TRUE),
('YMCA Camp Mountain Laurel Day Camp', 'Hamden/North Haven YMCA (Central Connecticut Coast YMCA)', 'https://cccymca.org/locations/hamden/camp/', 'https://ymcaccc.sgasoftware.com/Sales/Public', 'Campmtlaurel@cccymca.org', '203-535-2569', '2705 Downes Road', 'Hamden', 'CT', '06514', 'Connecticut', 'day', ARRAY['general','outdoor','sports']::text[], NULL, ARRAY['Swim lessons and recreational swim','Archery','STEAM activities','Hiking','Active games and sports','Arts and crafts','Ropes course','Climbing wall','Gaga','Specialty weeks: pottery, fort building, engineering, photography, music, theater, dance, cooking, sports, wilderness survival','Swim camps and Aquatic Leader program','Counselor in Training program (ages 14-15)']::text[], NULL, 3, 15, NULL, 9, 'The Hamden/North Haven YMCA''s summer day camp on twenty wooded acres at 2705 Downes Road in Hamden, for ages 3 through entering 9th grade, plus a CIT program for ages 14-15. Campers swim in an outdoor pool and do archery, STEAM, hiking, sports, ropes and climbing, and arts and crafts, with weekly themes and specialty camps. Camp runs 9:00 to 4:00.', NULL, NULL, 110, 365, 325, 'week', TRUE, TRUE, NULL, TRUE, 'A $50 deposit per camper per week is due at registration and cannot be refunded or transferred.', 'The Y works with children of all abilities. Families of a child who needs social, behavioral or medical accommodations are asked to contact the Camp Director.', 'Camp has an outdoor swimming pool. Weekly activities include swim lessons and recreational swim; beginner and intermediate swim camps are offered, and the intermediate camp requires a skills assessment.', TRUE, 'https://cccymca.org/wp-content/uploads/CML-SUMMER-DAY-CAMP-GUIDE-1.pdf', 2026, '863daef5-0594-5ea9-a968-8dea840d1623', 'ymca-camp-mountain-laurel-day-camp-hamden', ST_GeogFromText('SRID=4326;POINT(-72.8968 41.3959)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://cccymca.org/locations/hamden/camp/','https://cccymca.org/wp-content/uploads/CML-SUMMER-DAY-CAMP-GUIDE-1.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('YMCA of Greenwich School-Aged Summer Camps', 'YMCA of Greenwich', 'https://greenwichymca.org/programs/childcare/School-Aged-Camp', 'https://operations.daxko.com/online/5449/Security/login.mvc/find_account?return_url=%2fOnline%2f5449%2fRedirect%2fHomepage.mvc', 'Info@gwymca.org', '203.869.1630', '50 East Putnam Avenue', 'Greenwich', 'CT', '06830', 'Connecticut', 'day', ARRAY['sports','nature','STEM','arts','technology']::text[], NULL, ARRAY['swimming','arts & crafts','field trips','STEM projects','sports','imaginative play','canoeing','archery','hiking','rock climbing','low ropes course','coding','3D printing','AI','stop motion animation','video creation','entrepreneurship']::text[], NULL, 3, NULL, 0, 10, 'Weekday summer day camps for kids from age 3 through 10th grade, run at the YMCA of Greenwich and at Camp Seton in Greenwich. The options are a full-day general camp (Discovery Camp), an outdoor Adventure Camp at Camp Seton, half-day camps that follow Greenwich summer school, and short specialty camps for coding and entrepreneurship.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, NULL, TRUE, NULL, NULL, 'Discovery Camp includes swimming. Adventure Camp at Camp Seton includes canoeing and swimming. The page does not give swim test or lifeguard details.', NULL, NULL, 2026, '04a0d6aa-3328-5352-a32e-446d53bc432e', 'ymca-of-greenwich-school-aged-summer-camps-greenwich', ST_GeogFromText('SRID=4326;POINT(-73.6282 41.0262)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://greenwichymca.org/programs/childcare/School-Aged-Camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Zoo Patrol', 'Connecticut Zoological Society (Connecticut''s Beardsley Zoo)', 'https://beardsleyzoo.org/education/zoo-patrol/', 'http://zoopatrol26.givesmart.com/', 'programming@beardsleyzoo.org', '203-394-6563', '1875 Noble Avenue', 'Bridgeport', 'CT', '06610', 'Connecticut', 'day', ARRAY['nature','STEM']::text[], NULL, ARRAY['Guided exploration of zoo areas','Staff presentations on animals, enrichment and veterinary care','Zoo-themed games','Art activities','Scientific observation, tracking and artifact identification']::text[], NULL, 7, 13, NULL, NULL, 'A half-day summer week at Connecticut''s Beardsley Zoo in Bridgeport for ages 7-10 and 11-13, running 9 am to 12:30 pm. Each day children explore a different area of the zoo outdoors, hear staff talks on animal care, enrichment and veterinary care, and play zoo-themed games and art activities.', NULL, NULL, 295, 320, 320, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'a329799f-3e15-59e3-b61f-3fcae768dfb7', 'zoo-patrol-bridgeport', ST_GeogFromText('SRID=4326;POINT(-73.1958 41.1874)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://beardsleyzoo.org/education/zoo-patrol/','https://e.givesmart.com/events/N8V/']::text[], '2026-11-13', '2026-11-13', TRUE)
